entries[101769] = { ["name"] = "Recipe: Stuffed Lushrooms", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to prepare Stuffed Lushrooms.\nSell Price:\nStuffed Lushrooms\nUse: Restores 5288 health and ( 1375 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 30 Stamina for 1 hour.\n\"Filled with well-aged cheese and baked to perfection.\"\nSell Price:\nRequires Aged Mogu'shan Cheese , Fresh Lushroom (5)" }
entries[101770] = { ["name"] = "Recipe: Fluffy Silkfeather Omelet", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to prepare a Fluffy Silkfeather Omelet.\nSell Price:\nFluffy Silkfeather Omelet\nUse: Restores 5288 health and ( 1375 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 20 Strength for 1 hour.\n\"Fresh eggs and well-aged cheese.\"\nSell Price:\nRequires Aged Mogu'shan Cheese , Fresh Silkfeather Hawk Eggs (5)" }
